import numpy as np
def comps(g,bg):
    g=np.array(g); seen=np.zeros(g.shape,bool); out=[]
    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            if g[r,c]!=bg and not seen[r,c]:
                st=[(r,c)]; seen[r,c]=1; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<g.shape[0] and 0<=nb<g.shape[1] and not seen[na,nb] and g[na,nb]!=bg:
                                seen[na,nb]=1; st.append((na,nb))
                out.append(cells)
    return out
